INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_2_24',
  'Which prompt engineering technique involves providing the model with a few examples of input-output pairs to guide its response for a new task?',
  'mcq',
  '["Zero-shot prompting","Few-shot prompting","Chain-of-thought prompting","ReAct prompting"]'::json,
