INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_1_45',
  'Which of the following is a valid vector store that can be integrated with Amazon Bedrock Knowledge Bases to store embeddings for RAG?',
  'mcq',
  '["Amazon S3 for object storage.","Amazon DynamoDB for NoSQL document storage.","Amazon OpenSearch Service.","Amazon Redshift for data warehousing."]'::json,
  '{2}'::int[],
  'Option C (correct) is a valid vector store supported by Amazon Bedrock Knowledge Bases. Amazon OpenSearch Service can store and search vector embeddings. Options A, B, and D are general-purpose AWS data services but are not inherently designed as vector stores for similarity search with embeddings.',
  NOW(),
  'quiz_domain7_1',
