INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_23',
  'Which evaluation dimension assesses whether a foundation model''s output is factually accurate and consistent with provided source information?',
  'mcq',
  '["Toxicity","Relevance","Groundedness","Coherence"]'::json,
  '{2}'::int[],
  'Option C (correct) refers to groundedness, which is the extent to which a model''s output is supported by and consistent with the factual information it was given or retrieved. Option A (toxicity) relates to harmful content. Option B (relevance) refers to how well the output addresses the prompt. Option D (coherence) refers to the logical flow and understandability of the text.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  57,
  NULL,
  NULL,
  'm_7_4',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_24',
