INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_3_29',
  'Which parameter-efficient fine-tuning (PEFT) technique involves adding small, trainable matrices (adapters) to a pre-trained model''s layers, allowing for efficient adaptation with minimal computational overhead?',
  'mcq',
  '["Full fine-tuning","LoRA (Low-Rank Adaptation)","Continued pre-training","RLHF (Reinforcement Learning from Human Feedback)"]'::json,
  '{1}'::int[],
  'Option B (correct) describes LoRA (Low-Rank Adaptation), a popular PEFT technique that injects small, trainable matrices into the transformer layers of a pre-trained model. This allows for efficient fine-tuning by only updating these small matrices, significantly reducing computational and storage costs compared to full fine-tuning. Option A updates all model parameters. Option C is a pre-training phase. Option D is a method for aligning models with human preferences.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  98,
  NULL,
  NULL,
  'm_7_3',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
