INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_1_77',
  'A healthcare provider is deploying an AI system to assist in diagnosing rare diseases. Given the high-stakes nature of medical diagnoses, what responsible AI pattern is crucial to ensure accountability and error correction?',
