INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_9_m_9_1_55',
  'A data scientist needs to grant an Amazon SageMaker notebook access to specific Amazon S3 buckets for training data. Which AWS service should be used to define the necessary permissions?',
  'mcq',
  '["AWS IAM","AWS KMS","Amazon VPC","AWS CloudTrail"]'::json,
  '{0}',
  'Option A (AWS IAM) is the correct service for defining and managing access permissions to AWS resources, including granting SageMaker notebooks access to S3 buckets. IAM roles and policies are fundamental for controlling who can access what in AWS. Option B (AWS KMS) is used for managing encryption keys, not access permissions. Option C (Amazon VPC) is for creating isolated network environments. Option D (AWS CloudTrail) is for logging API activity, not for defining access control.',
  NOW(),
  'quiz_domain9_1',
  NOW(),
  1,
  NULL,
  NULL,
  'm_9_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_9_m_9_1_56',
  'Which AWS service is primarily used to encrypt training data and model artifacts stored at rest in Amazon S3 for an AI/ML workload?',
