INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_9_m_9_2_48',
  'A company is building an AI system that processes sensitive personal information. To comply with data privacy regulations, they need to maintain a clear record of where the data originated, how it was transformed, and who accessed it. Which data governance practice addresses this requirement?',
  'mcq',
  '["Data minimization","Model risk management","Data lineage tracking","Prompt injection mitigation"]'::json,
  '{2}',
  'Option C (Data lineage tracking) is the data governance practice that addresses the requirement to maintain a clear record of data''s origin, transformations, and access history. This provides transparency and accountability for data handling, crucial for privacy compliance. Option A (Data minimization) focuses on collecting only necessary data. Option B (Model risk management) deals with risks associated with the AI model itself. Option D (Prompt injection mitigation) is a security measure for generative AI.',
  NOW(),
  'quiz_domain9_1',
  NOW(),
  56,
  NULL,
  NULL,
  'm_9_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

