INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_9_m_9_2_50',
  'A compliance officer needs to regularly audit the configuration of AWS resources used by AI/ML workloads to ensure they adhere to internal security policies. Which AWS service can be used to continuously monitor and record resource configurations and flag non-compliant settings?',
  'mcq',
  '["AWS CloudTrail","AWS KMS","AWS Config","Amazon VPC"]'::json,
  '{2}',
