INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_5_m_5_2_60',
  'A company needs to process large volumes of text data for insights and language translation. Which AWS AI services are designed to address these specific text-related tasks? (Select TWO.)',
  'multiple',
  '["Amazon Comprehend","Amazon Translate","Amazon Rekognition","Amazon Polly","Amazon Forecast"]'::json,
  '{0,1}'::int[],
  'Option A (Amazon Comprehend) is correct as it is a natural language processing (NLP) service that uses machine learning to find insights and relationships in text. Option B (Amazon Translate) is correct as it provides high-quality neural machine translation. Option C (Amazon Rekognition) is an image and video analysis service. Option D (Amazon Polly) is a text-to-speech service. Option E (Amazon Forecast) is a time-series forecasting service.',
  NOW(),
  'quiz_domain5_1',
  NOW(),
  17,
  NULL,
  NULL,
  'm_5_2',
  'easy'
