INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_2_95',
  'What are key aspects of human-centered design principles when creating explainable AI systems to foster user trust and effective interaction? (Select TWO.)',
