-- ─────────────────────────────────────────

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_5_m_5_1_69',
  'An AI practitioner is explaining the relationship between Artificial Intelligence, Machine Learning, and Deep Learning to a new team member. Order these concepts from the broadest to the most specific.',
  'ordering',
  '["Deep Learning","Artificial Intelligence","Machine Learning"]'::json,
  '{1,2,0}'::int[],
  'Artificial Intelligence (Option B) is the broadest concept, encompassing any technique that enables computers to mimic human intelligence. Machine Learning (Option C) is a subset of AI that allows systems to learn from data without explicit programming. Deep Learning (Option A) is a specialized subset of Machine Learning that uses neural networks with many layers to learn complex patterns.',
  NOW(),
  'quiz_domain5_1',
  NOW(),
  16,
  NULL,
  NULL,
  'm_5_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_5_m_5_1_70',
  'A new team member is learning about Artificial Intelligence and its subfields. Order the following concepts from the broadest to the most specialized.',
  'ordering',
  '["Deep Learning","Artificial Intelligence","Machine Learning","Generative AI"]'::json,
  '{1,2,0,3}'::int[],
  'Artificial Intelligence (Option B) is the broadest field aiming to create intelligent machines. Machine Learning (Option C) is a subset of AI that enables systems to learn from data without explicit programming. Deep Learning (Option A) is a specialized subset of Machine Learning that uses neural networks with multiple layers. Generative AI (Option D) is a specific type of AI, often leveraging deep learning, focused on creating new content, making it a more specialized application within the broader AI landscape.',
  NOW(),
  'quiz_domain5_1',
