INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_2_68',
  'A developer is iteratively refining a prompt for an Amazon Bedrock foundation model. Arrange the following steps in the correct order for effective prompt refinement.',
  'ordering',
  '["Analyze model output for desired quality and errors.","Modify the prompt based on analysis and specific issues.","Test the modified prompt with new inputs.","Submit the initial prompt to the model."]'::json,
  '{3,0,1,2}'::int[],
  'Effective prompt refinement is an iterative process. Option D (Submit the initial prompt to the model) is the first step to get a baseline. Option A (Analyze model output for desired quality and errors) follows, as you need to understand the current performance. Option B (Modify the prompt based on analysis and specific issues) is the next logical step to address identified problems. Finally, Option C (Test the modified prompt with new inputs) is crucial to validate the changes and continue the cycle.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  1,
  NULL,
  NULL,
  'm_7_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_2_69',
  'To improve the consistency of a foundation model''s output for a specific task using few-shot prompting, arrange these steps in the logical sequence.',
  'ordering',
  '["Provide the model with the actual input for inference.","Craft a clear instruction for the model.","Define the desired task and output format.","Include several examples of input-output pairs."]'::json,
  '{2,1,3,0}'::int[],
  'For few-shot prompting, the process begins by Option C (Define the desired task and output format) to establish the goal. Next, Option B (Craft a clear instruction for the model) provides the explicit guidance. Option D (Include several examples of input-output pairs) then demonstrates the desired behavior. Finally, Option A (Provide the model with the actual input for inference) is given for the model to generate its response based on the learned examples.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  2,
  NULL,
  NULL,
  'm_7_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

