INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_1_65',
  'When selecting a foundation model from Amazon Bedrock for a new application, arrange the following criteria in a typical evaluation order.',
