INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_2_114',
  'A data scientist is tasked with understanding the decision-making process of a complex, black-box AI model. Order the typical actions a data scientist would take to interpret such a model.',
  'ordering',
  '["Review individual prediction explanations to understand specific decisions","Gather a representative set of prediction samples","Deploy the trained black-box model","Generate global feature importance scores for the model"]'::json,
  '{2,1,3,0}'::int[],
  'Interpreting a black-box model begins with deploying the trained model (Option C). Next, a representative set of prediction samples is gathered (Option B) to analyze. Global feature importance scores are then generated (Option D) to understand which features generally influence the model most. Finally, individual prediction explanations are reviewed (Option A) to understand the factors behind specific decisions.',
