INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_2_118',
  'An organization is developing an AI system for medical image analysis. To ensure transparency and build user trust, they want to integrate explainability early in the design phase. Order the steps to embed explainability as a core design principle.',
  'ordering',
  '["Validate the generated explanations with medical experts and end-users","Select models that are inherently interpretable or plan for robust post-hoc explanations","Define clear explainability requirements and target audience","Develop and train the AI model, integrating explainability tools like SageMaker Clarify"]'::json,
  '{2,1,3,0}'::int[],
  'Integrating explainability as a core design principle starts with defining clear requirements and understanding the target audience for explanations (Option C). This guides the selection of models that are either inherently interpretable or for which robust post-hoc explanation methods are planned (Option B). The AI model is then developed and trained, actively integrating explainability tools like Amazon SageMaker Clarify (Option D). Finally, the generated explanations are validated with domain experts and end-users (Option A) to ensure they are meaningful and trustworthy. This proactive approach avoids treating explainability as an afterthought.',
  NOW(),
  'quiz_domain8_1',
  NOW(),
  40,
  NULL,
  NULL,
  'm_8_2',
  'medium'
) ON CONFLICT (id) DO NOTHING;

