  '{"left":["Model","Dataset","Features"],"right":["Output of a training process, representing learned patterns","Collection of data samples used for training and evaluation","Input variables or attributes used by the model for prediction"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_5_1',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_5_m_5_1_93',
  'Match common Machine Learning use cases to their primary objectives.',
  'matching',
