INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_5_m_5_2_97',
  'Match the core principles of Responsible AI to their definitions.',
  'matching',
  '{"A":"Fairness","B":"Transparency","C":"Privacy"}'::json,
  NULL,
  'Fairness (left: 0) in Responsible AI means ensuring that models do not perpetuate or amplify biases present in training data, leading to discriminatory outcomes. Transparency (left: 1) involves making AI systems understandable and interpretable, so users can comprehend their decisions. Privacy (left: 2) focuses on safeguarding sensitive information used by and generated from AI systems. Overlooking bias and fairness concerns (anti-pattern ap-1.2-002) can lead to significant ethical and business risks.',
  NOW(),
  'quiz_domain5_1',
  NOW(),
  26,
  '{"left":["Fairness","Transparency","Privacy"],"right":["Ensuring AI models produce unbiased and equitable outcomes","Providing clear explanations of how AI systems make decisions","Protecting sensitive user data throughout the AI lifecycle"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_5_2',
