INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_6_m_6_1_97',
  'Match the prompt engineering technique to its description.',
  'matching',
  '{"A":"Zero-shot prompting","B":"Few-shot prompting","C":"Chain-of-thought prompting"}'::json,
  NULL,
  'Zero-shot prompting (left: 0) involves asking an LLM to perform a task without providing any examples in the prompt. Few-shot prompting (left: 1) includes a few examples in the prompt to guide the LLM''s response. Chain-of-thought prompting (left: 2) encourages the LLM to explain its reasoning process step-by-step before providing the final answer.',
  NOW(),
