INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_6_m_6_1_100',
  'Match the LLM concept to its explanation.',
  'matching',
  '{"A":"Hallucination","B":"Context window","C":"Tokenization"}'::json,
  NULL,
  'Hallucination (left: 0) refers to an LLM generating plausible-sounding but factually incorrect or nonsensical information. The Context window (left: 1) defines the maximum number of tokens an LLM can process in a single input-output interaction. Tokenization (left: 2) is the process of breaking down raw text into smaller units called tokens for an LLM to process.',
