INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_6_m_6_1_101',
  'Match the LLM output characteristic to its associated inference parameter.',
  'matching',
  '{"A":"Deterministic output","B":"Creative output","C":"Concise output"}'::json,
  NULL,
  'Deterministic output (left: 0), where the LLM produces highly focused and consistent responses, is typically achieved by setting Temperature to 0. Creative output (left: 1), which is more diverse and imaginative, is encouraged by using a higher Temperature value. Concise output (left: 2) can be controlled by setting a lower value for the Max tokens parameter, limiting the length of the response.',
  NOW(),
  'quiz_domain6_1',
  NOW(),
  24,
  '{"left":["Deterministic output","Creative output","Concise output"],"right":["Temperature = 0","Higher Temperature","Lower Max tokens"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_6_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_6_m_6_1_102',
  'Match the LLM anti-pattern to its consequence.',
  'matching',
  '{"A":"Ignoring context window","B":"Trusting LLM outputs","C":"Temperature 0 for all"}'::json,
  NULL,
  'Ignoring context window limits (left: 0) when processing long documents leads to incomplete responses because content exceeding the window is truncated. Trusting LLM outputs without validation (left: 1) for factual or high-stakes tasks can result in incorrect factual information due to hallucinations. Setting temperature to 0 for all generative AI use cases (left: 2) produces deterministic output, which is suboptimal for tasks requiring creativity or brainstorming.',
  NOW(),
  'quiz_domain6_1',
  NOW(),
  25,
  '{"left":["Ignoring context window","Trusting LLM outputs","Temperature 0 for all"],"right":["Incomplete responses","Incorrect factual info","Suboptimal creativity"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_6_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
