  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_6_1',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_6_m_6_1_104',
  'Match the tokenization-related terms to their correct descriptions.',
  'matching',
  '{"A":"Token","B":"Tokenization","C":"Context Window"}'::json,
  NULL,
  'A Token is the fundamental unit of text that a large language model processes, which can be a word, part of a word, or a character. Tokenization is the process of converting raw text into these tokens. The Context Window refers to the maximum number of tokens an LLM can process in a single input or generate in a single output, impacting the amount of information it can consider.',
  NOW(),
  'quiz_domain6_1',
  NOW(),
  27,
  '{"left":["Token","Tokenization","Context Window"],"right":["Basic unit of text for LLMs","Process of breaking text into tokens","Maximum input/output length for LLMs"]}'::json,
