INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_6_m_6_1_116',
  'Match the core component of the Transformer architecture, foundational to modern large language models, to its primary function.',
  'matching',
  '{"A":"Transformer architecture","B":"Encoder","C":"Decoder"}'::json,
  NULL,
  'The Transformer architecture (left[0]) is a neural network model that relies heavily on self-attention mechanisms to process input sequences and generate output sequences, forming the backbone of most modern LLMs (right[0]). The Encoder (left[1]) part of the Transformer processes the input sequence, extracting contextual information and creating a rich representation of the input (right[1]). The Decoder (left[2]) then takes this contextual representation from the encoder (or directly processes an input sequence in decoder-only models) and generates the output sequence, token by token (right[2]).',
  NOW(),
  'quiz_domain6_1',
  NOW(),
  39,
  '{"left":["Transformer architecture","Encoder","Decoder"],"right":["Attention-based neural network for sequences","Processes input sequence to extract context","Generates output sequence based on context"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_6_1',
  'hard'
) ON CONFLICT (id) DO NOTHING;

