INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_6_m_6_2_95',
  'Match the limitations of generative AI to their descriptions.',
  'matching',
  '{"A":"Hallucinations","B":"Lack of Interpretability","C":"Nondeterminism"}'::json,
  NULL,
  'Hallucinations refer to the tendency of LLMs to generate false or misleading information that appears coherent. Lack of Interpretability means it can be challenging to understand the internal reasoning or decision-making process of complex LLMs. Nondeterminism implies that an LLM might produce different outputs for the exact same input prompt, especially with higher temperature settings.',
  NOW(),
  'quiz_domain6_1',
  NOW(),
  49,
  '{"left":["Hallucinations","Lack of Interpretability","Nondeterminism"],"right":["Generating incorrect but plausible output","Difficulty understanding LLM decisions","Varied outputs for identical inputs"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_6_2',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
