INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_6_m_6_2_98',
  'Match business value metrics to how they measure generative AI impact.',
  'matching',
  '{"A":"Efficiency","B":"Accuracy","C":"Conversion Rate"}'::json,
  NULL,
  'Efficiency measures how generative AI reduces the time or resources required to complete tasks, such as automating content creation. Accuracy assesses the correctness and relevance of the AI''s generated output, crucial for tasks like summarization or Q&A. Conversion Rate tracks the percentage of users who complete a desired action after interacting with AI-generated content or assistance, indicating business impact.',
