INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_1_87',
  'Match the foundation model selection criterion to its definition.',
  'matching',
  '{"A":"Latency","B":"Cost","C":"Modality"}'::json,
  NULL,
  'Latency (left[0]) refers to the time taken for a foundation model to generate a response (right[1]), which is crucial for real-time applications. Cost (left[1]) is the expense incurred per token processed or per inference request (right[2]), impacting the operational budget. Modality (left[2]) describes the type of data a model can process, such as text, images, or audio (right[0]).',
