INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_1_103',
  'Match each evaluation method for foundation model outputs to what it primarily assesses.',
  'matching',
  '{"A":"BLEU","B":"ROUGE","C":"Human Evaluation"}'::json,
  NULL,
  'BLEU (Bilingual Evaluation Understudy) primarily assesses n-gram overlap with a reference text, focusing on precision. ROUGE (Recall-Oriented Understudy for Gisting Evaluation) also measures n-gram overlap but focuses on recall, often used for summarization. Human Evaluation is critical for assessing subjective qualities like semantic quality, factual accuracy, and overall coherence, which automated metrics often miss (anti-pattern ap-3.1-002).',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  37,
  '{"left":["BLEU","ROUGE","Human Evaluation"],"right":["N-gram overlap with reference, precision","N-gram overlap with reference, recall","Semantic quality, factual accuracy, coherence"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_1',
  'hard'
) ON CONFLICT (id) DO NOTHING;

