INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_1_107',
  'Match the automated evaluation metric to its primary limitation for generative AI outputs.',
  'matching',
  '{"A":"BLEU score","B":"ROUGE score","C":"Perplexity"}'::json,
  NULL,
  'BLEU score measures n-gram overlap but doesn''t capture semantic meaning, factual accuracy, or overall coherence (anti-pattern ap-3.1-002). ROUGE score, similarly, focuses on n-gram overlap and recall but often fails to assess the coherence or relevance of generated text. Perplexity measures how well a language model predicts a sample of text, indicating fluency, but does not evaluate the content''s quality, truthfulness, or usefulness.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  41,
  '{"left":["BLEU score","ROUGE score","Perplexity"],"right":["Doesn''t capture semantic meaning or factual accuracy","Focuses on overlap, not coherence or relevance","Measures fluency, not content quality or truthfulness"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_1',
  'hard'
) ON CONFLICT (id) DO NOTHING;

