INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_86',
  'Match the foundation model evaluation dimension to its focus.',
  'matching',
  '{"A":"Accuracy","B":"Relevance","C":"Coherence"}'::json,
  NULL,
  'Accuracy (left[0]) in foundation model evaluation focuses on the correctness of factual information generated by the model (right[1]). Relevance (left[1]) assesses how pertinent the model''s output is to the user''s original query or prompt (right[2]). Coherence (left[2]) evaluates the logical consistency and smooth flow of the generated text (right[0]), ensuring it makes sense as a whole.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  42,
  '{"left":["Accuracy","Relevance","Coherence"],"right":["Logical consistency and flow of text.","Correctness of factual information.","Pertinence to the user''s query."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_4',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_87',
  'Match the evaluation dimension to its concern for foundation model outputs.',
  'matching',
  '{"A":"Toxicity","B":"Bias","C":"Groundedness"}'::json,
  NULL,
  'Toxicity (left[0]) as an evaluation dimension is concerned with the presence of harmful or offensive language in the model''s output (right[1]). Bias (left[1]) refers to unfair representation or perpetuation of stereotypes in the generated content (right[2]). Groundedness (left[2]) evaluates the model''s adherence to factual sources or provided context, preventing hallucinations (right[0]).',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  43,
  '{"left":["Toxicity","Bias","Groundedness"],"right":["Adherence to factual sources.","Presence of harmful or offensive language.","Unfair representation or stereotypes."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_4',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_88',
  'Match the automated metric to its primary use for text generation evaluation.',
  'matching',
  '{"A":"BLEU","B":"ROUGE","C":"BERTScore"}'::json,
  NULL,
  'BLEU (left[0]) is an automated metric primarily used to measure the n-gram overlap between a generated text and a reference text (right[0]). ROUGE (left[1]) evaluates text generation by comparing the recall and precision of n-grams between the generated and reference texts (right[2]), often used for summarization. BERTScore (left[2]) compares semantic similarity between generated and reference sentences using contextual embeddings from BERT (right[1]), offering a more nuanced evaluation than n-gram overlap.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  44,
  '{"left":["BLEU","ROUGE","BERTScore"],"right":["Measures n-gram overlap with reference.","Compares semantic similarity using BERT embeddings.","Evaluates recall and precision of n-grams."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_4',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_89',
  'Match the evaluation method to its characteristic.',
  'matching',
  '{"A":"Human evaluation","B":"Benchmark datasets","C":"A/B testing"}'::json,
  NULL,
  'Human evaluation (left[0]) involves using human judgment to assess the quality, relevance, and accuracy of foundation model outputs (right[1]), which is crucial for subjective aspects. Benchmark datasets (left[1]) are standardized collections of data used for comparative testing and performance measurement across different models (right[2]). A/B testing (left[2]) is a method to compare two different versions of a model or application in a live production environment (right[0]) to determine which performs better.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  45,
  '{"left":["Human evaluation","Benchmark datasets","A/B testing"],"right":["Compares two model versions in production.","Uses human judgment for quality assessment.","Standardized datasets for comparative testing."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_4',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_90',
  'Match the Amazon Bedrock feature to its role in model evaluation and safety.',
  'matching',
  '{"A":"Model Evaluation","B":"Guardrails","C":"Shadow deployment"}'::json,
  NULL,
  'Amazon Bedrock Model Evaluation (left[0]) is a feature that allows users to evaluate foundation model performance using automated metrics and human reviews (right[1]). Amazon Bedrock Guardrails (left[1]) are used to filter harmful content, redact PII, and enforce topic denial lists in model outputs (right[0]), ensuring safe and responsible usage. Shadow deployment (left[2]) is a method for testing new model versions passively in production by routing a copy of live traffic to them without affecting user experience (right[2]).',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  46,
  '{"left":["Model Evaluation","Guardrails","Shadow deployment"],"right":["Filters harmful content from outputs.","Evaluates model performance with metrics.","Tests new model versions passively."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_4',
  'easy'
) ON CONFLICT (id) DO NOTHING;

