INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_94',
  'Match the evaluation method to its primary focus when assessing generative model quality.',
  'matching',
  '{"A":"BLEU score","B":"ROUGE score","C":"Human evaluation"}'::json,
  NULL,
  'BLEU score (left item 0) primarily measures n-gram overlap between a generated text and one or more reference texts, commonly used for machine translation evaluation. ROUGE score (left item 1) also measures n-gram overlap but is more frequently used for evaluating text summarization tasks. Human evaluation (left item 2) is crucial for assessing subjective aspects like semantic quality, coherence, and factual accuracy, which automated metrics like BLEU and ROUGE often fail to capture comprehensively (ap-3.1-002).',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  50,
  '{"left":["BLEU score","ROUGE score","Human evaluation"],"right":["N-gram overlap with reference (translation)","Overlap with reference (summarization)","Semantic quality and factual accuracy"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_4',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_95',
  'A company is deploying a new foundation model application and needs to evaluate its performance in a production environment. Match the deployment strategy to its evaluation characteristic.',
  'matching',
  '{"A":"A/B testing","B":"Shadow deployment","C":"Canary deployment"}'::json,
  NULL,
  'A/B testing (left item 0) involves routing live traffic to two different versions of a model or application to compare their performance directly. Shadow deployment (left item 1) means deploying a new model version alongside the current production version, sending copies of live traffic to the new version for monitoring without impacting actual users. Canary deployment (left item 2) is a strategy where a new version of an application or model is gradually rolled out to a small subset of users before a full rollout, allowing for real-world testing and quick rollback if issues arise.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  51,
  '{"left":["A/B testing","Shadow deployment","Canary deployment"],"right":["Compares two versions with live traffic","Monitors new version without impacting users","Gradually rolls out new version to users"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_4',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_4_96',
  'Match the Amazon Bedrock Guardrails feature to its content moderation capability.',
  'matching',
  '{"A":"Content filters","B":"PII redaction","C":"Topic denial lists"}'::json,
  NULL,
  'Content filters (left item 0) in Amazon Bedrock Guardrails detect and block content that falls into harmful categories like hate speech, sexual content, or violence. PII redaction (left item 1) automatically identifies and removes sensitive personally identifiable information from inputs or outputs. Topic denial lists (left item 2) allow users to define specific subjects or keywords that the model should avoid discussing, preventing off-topic or inappropriate conversations.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  52,
  '{"left":["Content filters","PII redaction","Topic denial lists"],"right":["Detects and blocks harmful categories","Removes sensitive personal information","Prevents discussion of specific subjects"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_4',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
