INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_3_76',
  'Match the foundation model training phase to its primary goal.',
  'matching',
  '{"A":"Pre-training","B":"Fine-tuning","C":"Instruction tuning"}'::json,
  NULL,
  'Pre-training (left[0]) is the initial phase where a foundation model learns broad patterns and knowledge from a vast amount of diverse data (right[1]). Fine-tuning (left[1]) adapts a pre-trained model to specific downstream tasks or domains using a smaller, labeled dataset (right[2]). Instruction tuning (left[2]) is a type of fine-tuning that aligns the model with human instructions and preferences (right[0]), improving its ability to follow commands.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  61,
  '{"left":["Pre-training","Fine-tuning","Instruction tuning"],"right":["Aligns model with human instructions.","Learns broad patterns from vast data.","Adapts model to specific tasks or domains."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_3_77',
  'Match the Parameter-Efficient Fine-Tuning (PEFT) technique to its description.',
  'matching',
  '{"A":"LoRA","B":"QLoRA","C":"Adapter tuning"}'::json,
  NULL,
  'LoRA (Low-Rank Adaptation) (left[0]) is a PEFT technique that injects small, low-rank matrices into existing model layers (right[2]) to update weights efficiently. QLoRA (left[1]) extends LoRA by performing Low-Rank Adaptation with quantization (right[1]), further reducing memory usage during fine-tuning. Adapter tuning (left[2]) involves adding small, trainable neural network layers (adapters) between existing layers of a frozen pre-trained model (right[0]).',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  62,
  '{"left":["LoRA","QLoRA","Adapter tuning"],"right":["Adds small, trainable layers (adapters).","Low-Rank Adaptation with quantization.","Injects low-rank matrices into model layers."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_7_m_7_3_78',
  'Match the training data requirement to its importance for fine-tuning.',
  'matching',
  '{"A":"Volume","B":"Quality","C":"Diversity"}'::json,
  NULL,
  'The Volume (left[0]) of training data is important because it prevents overfitting and improves the model''s overall performance (right[1]) by providing sufficient examples. The Quality (left[1]) of training data impacts the model''s ability to learn effectively and avoid propagating biases or errors (right[2]). Diversity (left[2]) in training data ensures the model generalizes well to various inputs and scenarios (right[0]), reducing bias and improving robustness.',
  NOW(),
  'quiz_domain7_1',
  NOW(),
  63,
  '{"left":["Volume","Quality","Diversity"],"right":["Ensures model generalizes well.","Prevents overfitting and improves performance.","Impacts model''s ability to learn effectively."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_7_3',
