-- ─────────────────────────────────────────

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_2_130',
  'Match model types and concepts to their characteristic regarding interpretability.',
  'matching',
  '{"A":"Transparent models","B":"Black-box models","C":"Explainable AI (XAI)"}'::json,
  NULL,
  'Transparent models (Option A), such as decision trees, are interpretable by design because their internal logic is easy to understand. Black-box models (Option B), like deep neural networks, are characterized by opaque decision-making, making it difficult to understand how they arrive at a prediction. Explainable AI (XAI) (Option C) refers to a set of techniques and methods that aim to make AI systems'' decisions more understandable to humans.',
  NOW(),
  'quiz_domain8_1',
  NOW(),
  20,
  '{"left":["Transparent models","Black-box models","Explainable AI (XAI)"],"right":["Interpretable by design","Opaque decision-making","Techniques for interpretability"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
