INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_2_131',
  'Match post-hoc explainability techniques to their primary purpose.',
  'matching',
  '{"A":"SHAP values","B":"Feature importance","C":"Model interpretability"}'::json,
  NULL,
  'SHAP (SHapley Additive exPlanations) values (Option A) provide a local explanation for individual model predictions by attributing the contribution of each feature. Feature importance (Option B) techniques offer a global understanding of which features have the most impact on a model''s overall predictions. Model interpretability (Option C) is the broader concept of understanding the model''s decision logic and how it processes inputs to produce outputs.',
  NOW(),
  'quiz_domain8_1',
  NOW(),
  21,
  '{"left":["SHAP values","Feature importance","Model interpretability"],"right":["Local explanation for predictions","Global understanding of feature impact","Understanding model''s decision logic"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_8_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_2_132',
  'Match AWS tools to their function in model explainability or related areas.',
  'matching',
