INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_2_134',
  'Match concepts related to model explainability to their definitions.',
  'matching',
  '{"A":"Post-hoc explainability","B":"Model transparency","C":"Model interpretability"}'::json,
  NULL,
  'Post-hoc explainability (Option A) refers to techniques applied after a model has been trained to explain its predictions. Model transparency (Option B) describes models that are inherently understandable by design, such as linear regressions or decision trees. Model interpretability (Option C) is the general ability to comprehend why a model made a specific decision or how it works internally.',
  NOW(),
  'quiz_domain8_1',
