) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_8_m_8_2_135',
  'Match anti-patterns in AI explainability to their potential consequences.',
  'matching',
  '{"A":"Black-box models for regulated industries","B":"Lack of explainability tools","C":"Treating XAI as an afterthought"}'::json,
  NULL,
  'Choosing black-box models for regulated industries without explainability requirements planning (Option A) is an anti-pattern that can lead to regulatory non-compliance, as regulations often demand explanations for automated decisions. A lack of explainability tools (Option B) results in an inability to justify model decisions, which can erode trust and hinder debugging. Treating XAI as an afterthought (Option C) is an anti-pattern that makes it significantly harder and more expensive to integrate explainability into existing AI systems later.',
  NOW(),
  'quiz_domain8_1',
  NOW(),
  25,
  '{"left":["Black-box models for regulated industries","Lack of explainability tools","Treating XAI as an afterthought"],"right":["Regulatory non-compliance","Inability to justify decisions","Increased cost and complexity to implement"]}'::json,
