  '{"left":["Encryption at rest","Encryption in transit","Access control"],"right":["Limiting resource permissions with policies","Protecting data stored on disks","Protecting data moving across networks"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_9_1',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_9_m_9_1_160',
  'A company processes sensitive customer data for AI model training. They need to ensure data is protected while stored and when accessed by authorized AI services. Match the requirement to the AWS service or feature.',
  'matching',
  '{"A":"Data at rest encryption","B":"Secure data transfer","C":"Granular service access"}'::json,
  NULL,
  'For Data at rest encryption (Option A), AWS KMS is used to manage cryptographic keys for encrypting data in services like Amazon S3 or Amazon EBS. For Secure data transfer (Option B), TLS/SSL protocols ensure that data is encrypted while in transit between clients and AWS services. For Granular service access (Option C), IAM policies define precise permissions for users and AWS services to interact with AI/ML resources, ensuring the principle of least privilege.',
  NOW(),
  'quiz_domain9_1',
  NOW(),
  14,
  '{"left":["Data at rest encryption","Secure data transfer","Granular service access"],"right":["IAM policies","AWS KMS","TLS/SSL"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_9_1',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
